<script setup>
import { ref, onMounted } from 'vue'
import { apiFetch } from '../lib/api.js'
const data = ref(null), busy = ref(false), error = ref(''), saved = ref(false)
const rows = [{ key: 'direct', title: 'Direct messages', hint: 'Someone sends a private message.' }, { key: 'group', title: 'Group messages', hint: 'A community or event chat has new messages.' }, { key: 'mention', title: 'Tagged in a group', hint: 'Someone selects the customer using @. Controlled separately from other group messages.' }]
async function load() { const r = await apiFetch('/admin/chat-notifications'); if (r.success) data.value = r.data; else error.value = r.message }
async function save() { busy.value = true; error.value = ''; saved.value = false; const r = await apiFetch('/admin/chat-notifications', { method: 'PUT', body: data.value.settings }); busy.value = false; if (r.success) { data.value = r.data; saved.value = true } else error.value = r.message }
onMounted(load)
</script>
<template>
  <section class="chat-settings" aria-labelledby="chat-settings-heading">
    <header><div><span class="chat-settings-tag">Marketplace · superadmin</span><h2 id="chat-settings-heading">Chat &amp; mention alerts</h2><p>Invite customers back to their unread conversations.</p></div><button class="btn btn-primary" :disabled="busy || !data" @click="save">{{ busy ? 'Saving…' : 'Save chat alerts' }}</button></header>
    <template v-if="data"><div class="chat-settings-status"><span v-if="data.preview">Test workspace · delivery simulated</span><span>{{ data.whatsapp_ready ? 'WhatsApp sender & template configured' : 'WhatsApp setup needed' }}</span></div>
    <div class="chat-settings-table"><table><thead><tr><th>When to notify</th><th>Email</th><th>WhatsApp</th></tr></thead><tbody><tr v-for="row in rows" :key="row.key"><td><b>{{ row.title }}</b><small>{{ row.hint }}</small></td><td v-for="channel in ['email','whatsapp']" :key="channel"><input type="checkbox" role="switch" v-model="data.settings[row.key][channel]" :aria-label="`${row.title}: ${channel}`" @change="saved = false" /></td></tr></tbody></table></div>
    <footer><p>Waits 2 minutes for the customer to read the chat. Unread alerts are grouped, with at most one per conversation per channel every 15 minutes. Customers can opt out; WhatsApp requires their chat opt-in.</p><p v-if="!data.whatsapp_ready">Connect Bookboll’s sender in <router-link to="/whatsapp">WhatsApp</router-link> and configure the approved chat alert template before WhatsApp delivery can start.</p><p v-if="data.delivery.needs_review" class="chat-settings-error">{{ data.delivery.needs_review }} deliveries need technical review. They won’t be retried automatically.</p></footer></template>
    <p v-if="saved" role="status">Chat alert settings saved.</p><p v-if="error" class="chat-settings-error" role="alert">{{ error }}</p>
  </section>
</template>
<style scoped>
.chat-settings{margin:22px 0;border:1px solid var(--border,#334155);border-radius:14px;background:var(--surface,#fff);overflow:hidden}.chat-settings header{padding:22px;display:flex;align-items:center;justify-content:space-between;gap:20px}.chat-settings-tag{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.chat-settings h2{font-size:20px;margin:7px 0}.chat-settings p{margin:5px 0;font-size:13px;line-height:1.6;color:var(--muted)}.chat-settings-status{display:flex;gap:10px;flex-wrap:wrap;padding:0 22px 18px}.chat-settings-status span{padding:6px 10px;background:#3b82f61a;color:var(--text);border-radius:6px;font-size:12px}.chat-settings-table{overflow:auto}.chat-settings table{width:100%;border-collapse:collapse}.chat-settings th,.chat-settings td{padding:15px 22px;border-top:1px solid var(--border,#334155);text-align:left}.chat-settings th{font-size:12px;color:var(--muted)}.chat-settings th:not(:first-child),.chat-settings td:not(:first-child){width:100px;text-align:center}.chat-settings td b{font-size:14px}.chat-settings td small{display:block;font-size:12px;color:var(--muted);margin-top:4px;max-width:520px}.chat-settings input{width:20px;height:20px;accent-color:#2563eb;cursor:pointer}.chat-settings footer{border-top:1px solid var(--border,#334155);padding:14px 22px}.chat-settings>p{padding:0 22px 16px}.chat-settings .chat-settings-error{color:#ef4444}@media(max-width:640px){.chat-settings header{align-items:flex-start;flex-direction:column}.chat-settings td,.chat-settings th{padding:12px}}
</style>
